import Vue from 'vue'
import Router from 'vue-router'
import Topo from '@/components/Topo'
import Test from '@/components/Test'

Vue.use(Router)

export default new Router({
  routes: [
    {
      path: '/',
      name: 'Topo',
      component: Topo
    },
    {
      path: '/topo',
      name: 'Topo',
      component: Topo
    },
    {
      path: '/test',
      name: "Test",
      component: Test
    }
  ]
})



