var debug = {
  container: null,
  isOpen: false,
  open: function(){
    debug.isOpen = true;
    debug.container.style = 'display: block;position:fixed;left:0;bottom:0;width:100%;height:130px;border-top:1px solid #aaa;background:#fff;';
  },
  close: function(){
    debug.isOpen = false;
    debug.container.style = 'display: none;';
  },
  logs: function(s){
    var log = null;

    if(!debug.isOpen){
      return;
    }

    log = document.createElement('div');
    log.style = 'border-bottom: 1px solid #aaa;padding: 0 5px;';
    log.innerHTML = s;

    if(debug.logsContainer.children[0]){
      debug.logsContainer.insertBefore(log, debug.logsContainer.children[0]);
    }else{
      debug.logsContainer.appendChild(log);
    }

  },
  bind: function(){
    debug.btnClear.addEventListener('click', function(e){
      debug.logsContainer.innerHTML = '';
    }, false);

    debug.btnClose.addEventListener('click', function(e){
      debug.container.style = 'display: none;';
    });
  },
  createDebug: function(){
    debug.container = document.createElement('div');
    debug.container.style = "position:fixed;left:0;bottom:0;width:100%;height:100px;border-top:1px solid #aaa;background:#fff;";

    debug.logsContainer = document.createElement('div');
    debug.logsContainer.style = "overflow-y:auto;height:100px";

    debug.btnContainer = document.createElement('div');
    debug.btnContainer.style = 'border-bottom: 1px solid #aaa;padding: 3px 5px;';

    debug.btnClear = document.createElement('button');
    debug.btnClear.innerHTML = 'Clear';
    debug.btnClear.style = 'padding: 3px 5px;';

    debug.btnClose = document.createElement('button');
    debug.btnClose.innerHTML = "X";
    debug.btnClose.style = 'float:right;width:1.5em;height:1.5em;border:0;border-radius:50%;background:#666;color:#fff;';

    debug.btnContainer.appendChild(debug.btnClear);
    debug.btnContainer.appendChild(debug.btnClose);
    debug.container.appendChild(debug.btnContainer);
    debug.container.appendChild(debug.logsContainer);
    document.body.appendChild(debug.container);
  },
  init: function(status){
    debug.createDebug();
    debug.bind();

    if(status){
      debug.open();
    }else{
      debug.close();
      return;
    }
  }
};

window.debug = debug;

export {debug}



