          topo.circleG = d3.select('.nodeLayer').selectAll('g');

          // add text
          // g.append('text')
          //   .attr('x', '0px')
          //   .attr('y', '34px')
          //   .attr('text-anchor', 'middle')
          //   .text(function(d){
          //     return d.txt;
          //   })
    
    
          // add image
          topo.circleG.append('svg:defs')
            .append('pattern')
            .attr('id', function(d){
              return d.id
            })
            .attr('patternUnits', 'userSpaceOnUse')
            .attr('width', 34)
            .attr('height', 34);
          
          var pat = d3.select('.nodeLayer').selectAll('pattern');
    
          pat.append("image")
            .attr("x", 0)
            .attr("y", 0)
            .attr("width", 34)
            .attr("height", 34)
            .attr("style", function(d){
              if(topo.curNode){
                if(topo.curNode.id == d.id){
                  return 'transform: translate(0px, 0px) scale(1.2)';
                }
              }
              return 'transform: translate(0, 0)';
            })
            .attr('xlink:href', topo.defautlImg);
    
          pat.append('image')
            .attr("x", 0)
            .attr("y", 0)
            .attr("width", 0)
            .attr("height", 0)
            .attr("style", function(d){
              if(topo.curNode){
                if(topo.curNode.id == d.id){
                  return 'transform: translate(0px, 0px) scale(1.2)';
                }
              }
              return 'transform: translate(0, 0)';
            })
            .attr('xlink:href', function(d){
              var self = this;
              var img = new Image();
    
              img.onload = function(){
                d3.select(self)
                  .attr('width', 34)
                  .attr('height', 34);
              }
    
              img.onerror = function(){
                d3.select(self).attr('xlink:href', topo.defautlImg)
                  .attr('width', 0)
                  .attr('height', 0);
              }
              img.src = d.imgSrc;
              
              return d.imgSrc;
            });

