<script>
    import {topo} from "../models/topo-mobile";
    import {debug} from "../models/debug";

    /**
     * 初始化
     */
    var getData = function(data){
      var djson = JSON.parse(data);
      debug.logs('before: ' + djson);
      var nodes = djson.nodes;
      var links = djson.linkes;

      
      var pwidth = document.documentElement.clientWidth || document.body.width;
      var pheight = document.documentElement.clientHeight || document.body.height;
      var wmax = pwidth / 2 + 200;
      var wmin = pwidth / 2 - 200;
      var hmax = pheight / 2 + 100;
      var hmin = pheight / 2 - 100;
      // console.log('max = ', wmax, 'min = ', wmin, 'hmax = ', hmax, 'hmin = ', hmin);
      for(var j = 0; j < nodes.length; j++){
        if(j == 0){
          nodes[j].x = pwidth / 2;
          nodes[j].y = pheight / 2;
          nodes[j].selected = true;
        }else{
          nodes[j].x = Math.floor(Math.random() * (wmax-wmin+1)+wmin);
          nodes[j].y = Math.floor(Math.random() * (hmax-hmin+1)+hmin);
        }
      }

      return {n: nodes, l: links}
    }
    window.initTopo = function(data){
      var nobj = null;
      debug.logs('data type: ' + (typeof data));
      if(typeof data === "string"){
        debug.logs('data = ' + data);
        nobj = getData(data);
      }else{
        try{
          debug.logs("json = " + JSON.stringify(data));
          nobj = getData(JSON.stringify(data));
        }catch(e){
          debug.logs("to json error");
        }
      }
      // debug.logs('data = ' + data);
      // nobj = getData(data);
      
      topo.init(nobj.n, nobj.l);
    }

    window.test = function(nodes, links){
      topo.init(nodes, links);
    }

    /**
     * 刷新
     */
    window.refreshNode = function(data){
      debug.logs('refresh data type: ' + (typeof data));
      var nobj = getData(data);
      topo.els.restartSVG(nobj.n, nobj.l);
    }


    export default {
