            {id: 2, reflexive: false, txt: 'Xiaomi', selected: false, imgSrc: '/static/image/1.jpg'},
            {id: 3, reflexive: false, txt: 'Meizu', selected: false, imgSrc: '/static/image/5.jpg'},
            {id: 4, reflexive: false, txt: 'Huawei', selected: false, imgSrc: '/static/image/5.jpg'},
