          var linkes = [
            {id: 1, source: 0, target: 1, left: false, right: true, txt: '1文件20.8G'},
            {id: 2, source: 0, target: 2, left: false, right: true, txt: '3文件20.8G'},
            {id: 3, source: 0, target: 3, left: false, right: true, txt: '5文件20.8G'},
            {id: 4, source: 0, target: 4, left: false, right: true, txt: '13文件20.8G'},
            {id: 5, source: 4, target: 5, left: false, right: true, txt: '8文件20.8G'},
            {id: 6, source: 4, target: 6, left: false, right: true, txt: '8文件0.8G'},
            {id: 7, source: 4, target: 7, left: false, right: true, txt: '11文件20.8G'},
            {id: 8, source: 4, target: 8, left: false, right: true, txt: '7文件20.8G'}
          ]

          var data = {nodes: nodees, linkes: linkes}

          initTopo(JSON.stringify(data))
          */
